window.TextAnimator=class{static lettersAndSymbols=["a","b","c","d","e","f","g","h","i","j","k","l","m","n","o","p","q","r","s","t","u","v","w","x","y","z","!","@","#","$","%","^","&","*","-","_","+","=",";",":","<",">",","];constructor(t){if(!t||!(t instanceof HTMLElement))throw Error("Invalid text element provided.");this.textElement=t,this.originalText=t.textContent||"",this.originalChars=[],this.splitText()}splitText(){this.splitter=new TextSplitter(this.textElement,{splitTypeTypes:"words, chars"}),this.originalChars=this.splitter.getChars().map(t=>t.innerHTML)}animate(){this.reset();let t=this.splitter.getChars();if(console.log("Animating text:",{element:this.textElement,chars:t.length,originalChars:this.originalChars.length}),!t.length){console.warn("No characters found to animate");return}let e=new TimelineLite;t.forEach((t,i)=>{if(!t){console.warn("Null character found at position",i);return}let n=t.innerHTML;TweenLite.set(t,{opacity:1});let s=new TimelineLite({delay:.03*i});for(let e=0;e<3;e++)s.to(t,.1,{opacity:1,onStart:function(){let e=TextAnimator.lettersAndSymbols[Math.floor(Math.random()*TextAnimator.lettersAndSymbols.length)];t.innerHTML=e}});s.to(t,.1,{opacity:1,onStart:function(){t.innerHTML=n}}),e.add(s,.02*i)}),this.textElement&&e.to(this.textElement,.5,{"--anim":1,ease:Power2.easeOut},0)}animateBack(){this.textElement&&(TweenLite.killTweensOf(this.textElement),TweenLite.to(this.textElement,.3,{"--anim":0,ease:Power2.easeIn}))}reset(){if(this.textElement)try{TweenLite.killTweensOf(this.textElement);let t=this.splitter.getChars();t&&t.length>0?t.forEach((t,e)=>{t&&(TweenLite.killTweensOf(t),e<this.originalChars.length&&(t.innerHTML=this.originalChars[e]||""))}):this.originalText&&(this.textElement.textContent=this.originalText),TweenLite.set(this.textElement,{"--anim":0})}catch(t){console.error("Error in reset:",t),this.originalText&&(this.textElement.textContent=this.originalText)}}};